    public void recordSnapshot(String sheetId, String user, Snapshot snapshot) {
        String prefix = " sheet=" + sheetId + " by=" + user;
        snapshot.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT" + prefix
